contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: takes selector to choose which logging function to call
    // 0..10 correspond to the various log... functions that return bool
    function run(uint8 selector, address maybeLogger, bytes32 b1, bytes32 b2, uint256 u, bytes calldata bs, uint256 fee, bytes calldata outp) public payable {
        require(selector <= 10, "selector out of range");
        // Ensure this contract is the caller when invoking c (it will be)
        // Set approvedLoggers[maybeLogger] to true or false via onlyOwner-only function requires owner = this contract on deployment.
        // We cannot assume ownership here; instead we will observe approvedLoggers for address(this) only via public getter
        // Read current approval for this contract
        bool approvedBefore = c.approvedToLog(address(this));

        bool reverted;
        bool ret;
        // Call different logging functions; they are non-view and change nothing except emitting and returning bool.
        // Each call must be a top-level statement.
        if (selector == 0) {
            // logCreated(address)
            try c.logCreated(maybeLogger) returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else if (selector == 1) {
            try c.logRedemptionRequested(msg.sender, b1, u, bs, fee, outp) returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else if (selector == 2) {
            try c.logGotRedemptionSignature(b1, b1, b2) returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else if (selector == 3) {
            try c.logRegisteredPubkey(b1, b2) returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else if (selector == 4) {
            try c.logSetupFailed() returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else if (selector == 5) {
            try c.logFraudDuringSetup() returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else if (selector == 6) {
            try c.logFunded() returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else if (selector == 7) {
            try c.logCourtesyCalled() returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else if (selector == 8) {
            try c.logStartedLiquidation(true) returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else if (selector == 9) {
            try c.logRedeemed(b1) returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        } else {
            try c.logLiquidated() returns (bool r) { reverted = false; ret = r; } catch { reverted = true; ret = false; }
        }

        // The general rule: these log... functions must NOT revert, and their returned boolean equals approvedToLog(address(this)) as read before call.
        // We assert: not reverted AND ret == approvedBefore
        assert(!reverted && ret == approvedBefore);
    }

    // allow receiving Ether if needed
    receive() external payable { }
}

