contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function with inputs: caller address (as an address), and selector to pick which log function to call,
    // plus arbitrary data needed for the calls. msg.sender for calls to c will be this contract, so we use only this contract's approval status.
    function run(uint8 which, address keepAddr, address requester, bytes32 digest, uint256 utxoSize, bytes calldata redeemerOutputScript, uint256 requestedFee, bytes calldata outpoint, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bool wasFraud, bytes32 txid) public payable {
        require(which <= 12, true);

        // Read approval status before any mutating call
        bool before = c.approvedToLog(address(this));

        // Ensure not approved precondition: if already approved we flip it to false by calling setApprovedLogger only if owner; but test cannot call onlyOwner. So we only proceed when not approved.
        // The require below enforces we only test the invariant for unapproved caller. If it's approved already the rule is vacuous for this run, so we skip by requiring false -> but we must allow runs; instead we require before == false so the checker explores inputs where contract is unapproved.
        require(before == false, "test requires this contract not pre-approved");

        bool ok;
        bool reverted;

        // Try each logging function; capture return or revert. Each call is top-level and mutating in c.
        if (which == 0) {
            // logCreated(address _keepAddress)
            try c.logCreated(keepAddr) returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 1) {
            try c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint) returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 2) {
            try c.logGotRedemptionSignature(digest, r, s) returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 3) {
            try c.logRegisteredPubkey(pubX, pubY) returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 4) {
            try c.logSetupFailed() returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 5) {
            try c.logFraudDuringSetup() returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 6) {
            try c.logFunded() returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 7) {
            try c.logCourtesyCalled() returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 8) {
            try c.logStartedLiquidation(wasFraud) returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 9) {
            try c.logRedeemed(txid) returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 10) {
            try c.logLiquidated() returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else if (which == 11) {
            try c.logExitedCourtesyCall() returns (bool ret) { ok = ret; reverted = false; } catch { ok = false; reverted = true; }
        } else {
            // which == 12 -> call the public getter approvedToLog itself (a view) to ensure non-mutating path
            bool ret = c.approvedToLog(address(this));
            ok = ret;
            reverted = false;
        }

        // After call, approvedToLog for this contract must remain false (logging functions should not change approval mapping),
        // and if caller was not approved the logging functions should return false and not revert (they return false early). However they could also revert; we accept either: if reverted==false then ok must be false. Also the mapping remains false.
        bool after = c.approvedToLog(address(this));

        assert(after == false && (reverted || ok == false));
    }

    receive() external payable {}
}

