        // We will call them once while potentialLogger may or may not be approved; these calls must use msg.sender == address(this)
        // Set the approved status for the potentialLogger to the opposite of beforeApproved to test both branches
        // OnlyOwner guard on setApprovedLogger: this test contract is the owner (checker deploys fresh C with this as deployer), so call is allowed
        c.setApprovedLogger(potentialLogger, !beforeApproved);
        bool afterFlip = c.approvedToLog(potentialLogger);

        // Now call logging functions from the test contract itself (msg.sender == address(this)). The contract has approvedLoggers mapping keyed by addresses.
        // We will record return values for both states by flipping approval and calling log functions as the test contract.

        // First, ensure this contract is (maybe) approved or not by setting its approval to false, call logs, then set to true and call again.
        c.setApprovedLogger(address(this), false);
        bool r1 = c.logCreated(address(0));
        bool r2 = c.logGotRedemptionSignature(c_digest, a, b);
