        // Now approve this contract and call again
        c.setApprovedLogger(address(this), true);
        bool s1 = c.logCreated(address(0));
        bool s2 = c.logGotRedemptionSignature(c_digest, a, b);
        bool s3 = c.logRegisteredPubkey(a, b);
        bool s4 = c.logSetupFailed();
        bool s5 = c.logFraudDuringSetup();
        bool s6 = c.logFunded();
        bool s7 = c.logCourtesyCalled();
