    // Test: when calling setApprovedLogger(owner-only) the mapping entry for _logger becomes _status
    // and all other observable approvedLoggers entries remain equal to their previous values.
    // We take an array of other addresses to check they are unchanged.
    function run(address ownerCaller, address logger, bool status, address check1, address check2) public payable {
        require(address(c) != address(0));
        // Pre-read approvals for the two other addresses
        bool before1 = c.approvedLoggers(check1);
        bool before2 = c.approvedLoggers(check2);

        // Attempt the call as this contract (msg.sender for c will be this contract). The provided ownerCaller
        // parameter encodes intention: if ownerCaller == address(this) we consider this contract as owner
        // but we cannot change msg.sender on external calls. Instead we rely on the fact the checker deploys
        // a fresh C and may set its owner to this test contract; we don't require any condition here.

        bool reverted;
        try c.setApprovedLogger(logger, status) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call, read the mapping values we can observe
        bool afterLogger = c.approvedLoggers(logger);
        bool after1 = c.approvedLoggers(check1);
        bool after2 = c.approvedLoggers(check2);

        // The general rule to assert:
        // If the call did not revert, then the mapping for `logger` must equal `status`,
        // and the other observed entries must be unchanged. If the call reverted, nothing is required
        // about `logger` but the other observed entries must remain unchanged (since reverted call shouldn't alter state).
        // Expressed as a single assert over parameters and observed values:
        assert((!reverted && afterLogger == status && after1 == before1 && after2 == before2) || (reverted && after1 == before1 && after2 == before2));
    }

    receive() external payable { }
}

