        try c.logGotRedemptionSignature(digest, r, s) returns (bool v) { r_got = v; } catch { r_got = false; }

        bool r_reg;
        try c.logRegisteredPubkey(signingX, signingY) returns (bool v) { r_reg = v; } catch { r_reg = false; }

        bool r_setup;
        try c.logSetupFailed() returns (bool v) { r_setup = v; } catch { r_setup = false; }

        bool r_fraud;
        try c.logFraudDuringSetup() returns (bool v) { r_fraud = v; } catch { r_fraud = false; }

        bool r_funded;
        try c.logFunded() returns (bool v) { r_funded = v; } catch { r_funded = false; }

        bool r_courtesy;
        try c.logCourtesyCalled() returns (bool v) { r_courtesy = v; } catch { r_courtesy = false; }

        bool r_started;
        try c.logStartedLiquidation(wasFraud) returns (bool v) { r_started = v; } catch { r_started = false; }

        bool r_redeemed;
        try c.logRedeemed(txid) returns (bool v) { r_redeemed = v; } catch { r_redeemed = false; }

        bool r_liquidated;
        try c.logLiquidated() returns (bool v) { r_liquidated = v; } catch { r_liquidated = false; }

        bool r_exited;
        try c.logExitedCourtesyCall() returns (bool v) { r_exited = v; } catch { r_exited = false; }

        // Read after-values of approvals for self and other
        bool after_self = c.approvedToLog(address(this));
        bool after_other = c.approvedToLog(maybeLoggerToToggle);

        // General rule to assert:
        // - The mapping approvedLoggers for any observed address must not change due to logging calls.
        // - If before_self was true then all log* calls must have returned true; if before_self was false then all log* calls must have returned false.
        // We allow setApprovedLogger attempt to have reverted (toggledReverted true) or succeeded; but in any case the invariant about logging return values must match the observable approval state before the logging calls.

        bool allReturnedSameAsBeforeSelf = (
            r_created == before_self &&
            r_redreq == before_self &&
            r_got == before_self &&
            r_reg == before_self &&
            r_setup == before_self &&
            r_fraud == before_self &&
            r_funded == before_self &&
            r_courtesy == before_self &&
            r_started == before_self &&
            r_redeemed == before_self &&
