contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test entry
    function run(address loggerToApprove, address otherAddr, bytes32 digest, bytes32 r, bytes32 s, bytes32 pubX, bytes32 pubY, bytes memory outpoint, bytes memory script, uint256 utxoSize, uint256 requestedFee, bytes32 txid, bool wasFraud) public payable {
        require(loggerToApprove != address(0) && otherAddr != address(0));

        // record approved status of two addresses before any logging calls
        bool beforeApprove_logger = c.approvedToLog(loggerToApprove);
        bool beforeApprove_other = c.approvedToLog(otherAddr);

        // Try to set approved logger using onlyOwner - this should revert because this contract is not owner
        bool setDidRevert;
        try c.setApprovedLogger(loggerToApprove, true) {
            setDidRevert = false;
        } catch {
            setDidRevert = true;
        }

        // Make several logging calls from this contract (msg.sender = this contract)
        bool r1;
        try c.logCreated(otherAddr) returns (bool ok) { r1 = ok; } catch { r1 = false; }

        bool r2;
        try c.logRedemptionRequested(otherAddr, digest, utxoSize, script, requestedFee, outpoint) returns (bool ok) { r2 = ok; } catch { r2 = false; }

        bool r3;
        try c.logGotRedemptionSignature(digest, r, s) returns (bool ok) { r3 = ok; } catch { r3 = false; }

        bool r4;
        try c.logRegisteredPubkey(pubX, pubY) returns (bool ok) { r4 = ok; } catch { r4 = false; }

        bool r5;
        try c.logSetupFailed() returns (bool ok) { r5 = ok; } catch { r5 = false; }

        bool r6;
        try c.logFraudDuringSetup() returns (bool ok) { r6 = ok; } catch { r6 = false; }

        bool r7;
        try c.logFunded() returns (bool ok) { r7 = ok; } catch { r7 = false; }

        bool r8;
        try c.logCourtesyCalled() returns (bool ok) { r8 = ok; } catch { r8 = false; }

        bool r9;
        try c.logStartedLiquidation(wasFraud) returns (bool ok) { r9 = ok; } catch { r9 = false; }

        bool r10;
        try c.logRedeemed(txid) returns (bool ok) { r10 = ok; } catch { r10 = false; }

        bool r11;
        try c.logLiquidated() returns (bool ok) { r11 = ok; } catch { r11 = false; }

        bool r12;
        try c.logExitedCourtesyCall() returns (bool ok) { r12 = ok; } catch { r12 = false; }

        // After making logging calls, ensure the approvedToLog statuses did not change for the observed addresses
        bool afterApprove_logger = c.approvedToLog(loggerToApprove);
        bool afterApprove_other = c.approvedToLog(otherAddr);

        // General rule assert: approved status for any observed address is unchanged, and each logX returned true only if beforeApprove_logger was true (since this contract's msg.sender is this contract, approvals are checked on msg.sender)
        // Note: r1..r12 correspond to whether the call returned true; they must be <= beforeApprove_this (which is approvedToLog(this contract address))
        bool beforeApprove_this = c.approvedToLog(address(this));

        // If the contract attempted to call setApprovedLogger and it didn't revert, ownership would be compromised; ensure that didn't silently change approvals
        // Compose condition: approvals unchanged AND for each log call, (returned true) implies (beforeApprove_this == true), and (returned false) implies either beforeApprove_this == false
        bool allReturnedImpliesApproval = true;
        bool[12] memory results = [r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12];
        for (uint i = 0; i < 12; i++) {
            if (results[i]) {
                if (!beforeApprove_this) { allReturnedImpliesApproval = false; break; }
            }
