contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try to set approval for a target logger to a desired boolean status.
    // We assert that if the call does not revert then c.approvedToLog(target) equals status,
    // and if it reverts then c.approvedToLog(target) remains equal to its prior value.
    function run(address target, bool status) public payable {
        require(target != address(0));

        // read before value via public getter
        bool before = c.approvedToLog(target);

        bool reverted;
        // calling setApprovedLogger may revert if this contract is not the owner
        try c.setApprovedLogger(target, status) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool after = c.approvedToLog(target);

        // General rule: if the call succeeded (not reverted) then after equals status.
        // If it reverted then the approval for target must be unchanged.
        assert((!reverted && after == status) || (reverted && after == before));
    }

    receive() external payable { }
}

